import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Görüntü bölmek kısa bir iştir: bir fotoğraf yüklersin, nasıl böleceğini seçersin, kesim çizgilerini incelersin ve parçaları indirirsin. Bu kılavuz ilk yüklemeden bitmiş döşemelere kadar her adımı sırayla gösterir.</p>\n<p>Başlamadan önce tek bir şeye ihtiyacın var: bölmek istediğin görüntü. Büyük ve yüksek çözünürlüklü bir görüntü en iyi döşemeleri verir, çünkü her döşeme tam orijinal boyutta kesilir. Küçük bir görüntü küçük döşemeler verir; bu yüzden sahip olduğun en büyük dosyayı kullan.</p>\n<p><a href=\"/tr/gorsel-bol\">Görüntü Bölücü</a> işi tarayıcında yapar. Hiçbir şey sunucuya yüklenmez, hesap gerekmez ve döşemeler ücretsiz indirilir. Aşağıdaki adımları izle; birkaç dakika içinde bölünmüş bir görüntün olur.</p>\n<h2 id=\"step-1-upload-your-image\">Adım 1: görüntünü yükle</h2>\n<p>Bölücüyü aç ve görüntünü yükleme alanına sürükle ya da cihazından bir dosya seçmek için tıkla. Görüntüyü Ctrl ve V ile doğrudan panodan da yapıştırabilirsin; bu dosya olarak kaydetmediğin ekran görüntüleri için işe yarar.</p>\n<p>Araç 20 MB'ye kadar JPG, PNG, WebP, HEIC, GIF, BMP ve SVG dosyalarını kabul eder. Çoğu fotoğraf ve ekran görüntüsü bu sınırın çok altındadır. iPhone'dan bir HEIC fotoğrafı yüklenir ve diğer dosyalar gibi bölünür.</p>\n<p>Görüntü yüklenir yüklenmez otomatik olarak 3'e 3 bir ilk bölme oluşturulur. Izgarayı ve numaralı kesim çizgilerini önizlemede hemen görürsün; bu ayarlama için bir başlangıç noktası verir.</p>\n<p>Yanlış dosyayı yüklediysen ayarlarını kaybetmeden değiştirebilirsin. Araç bölme modunu ve ızgara boyutunu koruyarak görüntüyü değiştirmeni sağlar; bu yüzden bir hata saniyelere mal olur, baştan başlamaya değil.</p>\n<h2 id=\"step-2-choose-a-split-mode\">Adım 2: bölme modu seç</h2>\n<p>Üç moddan birini seç: Izgara, Yatay Şeritler ya da Dikey Şeritler. Izgara görüntüyü satır ve sütunlara böler ve Instagram ızgaraları, yapbozlar ve posterler için moddur. Döşemeler görüntüyü yeniden oluşturmak için yan yana oturacaksa onu seç.</p>\n<p>Yatay şeritler görüntüyü üst üste satırlara keser. Uzun ekran görüntüleri, yüksek infografikler ve yukarıdan aşağıya okunan her şey için bu modu seç. Her şerit kendi başına iyi yazdırılan ya da yayımlanan geniş ve kısa bir görüntüdür.</p>\n<p>Dikey şeritler görüntüyü yan yana sütunlara keser. Geniş panoramalar ve banner'lar için bu modu seç; her şerit sahneyi sağa doğru sürdürür. Dikey şeritlere bölünmüş bir panorama kaydırılabilir bir kaydırıcı olarak çalışır.</p>\n<p>Hangi modun en iyi gittiğini bilmiyorsan Izgara ile başla. En esnek moddur ve görüntüyü kaybetmeden istediğin zaman şerit moduna geçebilirsin. Önizleme değişince güncellenir; bu yüzden farkı hemen görürsün.</p>\n<h2 id=\"step-3-set-rows-and-columns\">Adım 3: satır ve sütunları belirle</h2>\n<p>Izgara modunda satır ve sütun sayısını belirle. Üç satır ve üç sütun dokuz döşemeli klasik Instagram ızgarasını verir. İki çarpı iki basit bir dört döşemeli bölme verir ve dört çarpı dört daha büyük bir yapboz için on altı döşeme verir.</p>\n<p>Seçmeden önce döşeme boyutunu düşün. 3000 piksel bir fotoğraf 3'e 3 bölündüğünde 1000 piksel döşemeler verir; bunlar her yerde yayımlanabilecek kadar büyüktür. Aynı fotoğraf 10'a 10 bölündüğünde 300 piksel döşemeler verir; küçük ve yalnızca küçük resimler ya da mozaikler için uygundur.</p>\n<p>Şerit modlarında şerit sayısını belirle. Uzun bir ekran görüntüsü için dört yatay şerit, bir panorama için üç dikey şerit ve basit bir bölme için iki şerit. Şeritler görüntüyü eşit parçalara böler; bu yüzden sayı her parçanın boyutuna karar verir.</p>\n<p>Sayıları özgürce değiştir ve önizlemeyi izle. Ayarladıkça kesim çizgileri hareket eder ve döşeme sayısı güncellenir. Denemek bedavadır, çünkü hiçbir şey istemediğin sürece indirilmez.</p>\n<h2 id=\"step-4-use-a-preset\">Adım 4: hazır ayar kullan</h2>\n<p>Hazır ayarlar yaygın bölmeler için tek tıklamalı ayarlarıdır. 3'e 3 Instagram ızgara hazır ayarı çoğu kişinin ihtiyaç duyduğu ayardır ve araç yaygın ızgara boyutları ve şerit sayıları için başka hazır ayarlar da içerir. Bir hazır ayara dokun; satır ve sütunlar otomatik olarak dolar.</p>\n<p>Hazır ayar bir başlangıç noktasıdır. Dokunduktan sonra görüntün ya da planın başka bir biçim gerektiriyorsa sayıları ayarla. Hazır ayar yazmayı kurtarır ve son bölme üzerinde tam kontrol sende kalır.</p>\n<p>Görüntüleri sık böldüğünde hazır ayarlar kullan. Her hafta bir ızgara kuran bir sosyal medya yöneticisi her seferinde aynı hazır ayara dokunabilir ve aynı döşeme boyutlarını alabilir; bu profil ızgarasını bir yapbozdan diğerine tutarlı tutar.</p>\n<p>Hiçbir hazır ayar işine uymuyorsa satır ve sütunları elle belirle. Poster için 4'e 5 bir ızgara ya da banner için 1'e 6 bir şerit geçerli bölmelerdir ve elle kontroller 10'a 10'a kadar her kombinasyonu kapsar.</p>\n<h2 id=\"step-5-inspect-the-cut-lines\">Adım 5: kesim çizgilerini incele</h2>\n<p>Önizlemeye bak ve numaralı kesim çizgilerini bul. Her döşemenin tam olarak nerede başlayıp bittiğini gösterirler ve sayılar her döşemenin ızgaradaki konumunu, soldan sağa ve yukarıdan aşağıya belirtir.</p>\n<p>Bir kesim çizgisinin bir yüzden, metin satırından ya da önemli bir ayrıntıdan geçip geçmediğini incele. İki döşemeye bölünmüş bir yüz hata gibi görünür ve ortadan kesilmiş bir metin her iki döşemede de okunamaz. Bir kesim kötü çıkarsa ızgarayı değiştir ya da görüntüyü yeniden konumlandır.</p>\n<p>Kare olmayan bir kaynak görüntü için döşeme biçimlerini incele. Geniş bir fotoğraf 3'e 3 bölündüğünde kare değil, geniş döşemeler verir ve bu döşemeler kare bir ızgaraya uymayabilir.</p>\n<p>Satır ve sütunları ayarla ya da döşemelerin ihtiyaç duyduğun biçimde çıkması için kaynak görüntüyü önce kareye kırp.</p>\n<p>Görüntü çok ayrıntılıysa önizlemeye yaklaş. Küçük boyutta iyi görünen kesim çizgileri fotoğrafın yoğun bir bölgesinde bir sorunu gizleyebilir. Birkaç saniyelik inceleme bir indirmeyi ve yeniden bölmeyi kurtarır.</p>\n<h2 id=\"step-6-choose-the-tile-format\">Adım 6: döşeme biçimini seç</h2>\n<p>Döşemeler için biçimi seç. JPG fotoğraflarla iyi gider ve küçük dosyalar verir; bu sosyal gönderiler ve web kullanımı için istediğin şeydir. PNG grafikler, metin ve şeffaflığı olan her şeyle iyi gider, çünkü her pikseli tam tutar.</p>\n<p>Döşeme kalite kontrolü JPG döşemeler için görünür. JPG çıktısının sıkıştırmasını kontrol eder; bu yüzden yüksek bir değer daha fazla ayrıntı korur ve düşük bir değer daha küçük dosyalar verir. PNG döşemeler kayıpsızdır ve kalite kontrolü yoktur.</p>\n<p>Şeffaf PNG görüntüler için döşeme biçimi olarak PNG seç. JPG'nin şeffaflığı yoktur; bu yüzden JPG olarak dışa aktarılan şeffaf bir döşeme katı bir arka plan kazanır. Şeffaflık yalnızca onu destekleyen bir biçimde hayatta kalır.</p>\n<p>Biçimi hedefe uydur. Sosyal gönderiler ve yazdırma JPG ile iyi çalışırken sprite sayfaları, simgeler ve tasarım kaynakları PNG ister. Emin değilsen grafikler için PNG, fotoğraflar için JPG dışa aktar.</p>\n<h2 id=\"step-7-download-the-tiles\">Adım 7: döşemeleri indir</h2>\n<p>Döşemeleri hepsini bir anda almak için ZIP olarak indir. ZIP her döşemeyi sol üst köşeden okuma düzeninde numaralı bir dosya olarak içerir. Açtığında set kullanıma hazırdır; sayılar her döşemenin nereye gittiğini gösterir.</p>\n<p>Yalnızca birkaçına ihtiyacın varsa döşemeleri tek tek de indirebilirsin. Profil fotoğrafı için tek bir döşeme ya da banner için tek bir şerit tüm sete ihtiyaç duymaz ve ayrı indirme açma adımını atlar.</p>\n<p>İndirdikten sonra döşeme boyutlarını incele. Bir döşemeyi aç ve beklediğin boyutta olduğunu doğrula; özellikle tam piksellerin önemli olduğu yazdırma işleri ya da sprite sayfaları için. Şimdi yapılacak hızlı bir inceleme, döşemeleri kullanmadan önce yanlış bir ızgara ayarını yakalar.</p>\n<p>ZIP'i döşemeleri kullanana kadar yedek olarak sakla. Bir döşeme kaybolur ya da bir gönderi başarısız olursa ZIP seti başka bir bölme turu olmadan geri yükler. İş bitene kadar silme.</p>\n<h2 id=\"step-8-name-and-organize\">Adım 8: adlandır ve düzenle</h2>\n<p>İndirilen döşemeler numaralıdır ama dosya adları geneldir. İş anlamlı adlar gerektiriyorsa değiştir; örneğin yapboz-satir-1 ya da poster-doseme-a1 gibi. Net adlar, birkaç bölme aynı klasörde yaşadığında karışıklığı önler.</p>\n<p>Her bölmeyi kendi klasöründe tut. Döşemeleri sırayla içinde barındıran, işin adını taşıyan bir klasör, farklı projelerden numaralı dosyalarla dolu bir indirme klasöründen daha kolay yönetilir. Düzen, bir ızgarada dokuz ya da daha fazla döşeme olduğunda daha da önemli olur.</p>\n<p>Instagram ızgaraları için döşemeleri ızgara düzeninde değil, yayımlama düzeninde tut. Platform önce en yeni gönderiyi gösterir; bu yüzden döşemeler son ızgara konumundan ilkine doğru yayımlanmalıdır. Yayımlama düzenine göre sıralanmış bir klasör tahminleri ortadan kaldırır.</p>\n<p>Bölme ayarını işi tekrarlayacaksan bir yere not et. Kare bir görüntüden 3'e 3 bir ızgara hatırlanması kolaydır ama 85 JPG kaliteli özel 4'e 5 bir bölme değildir. Kısa bir not, ayarı bir dahaki sefere yeniden keşfetmeni kurtarır.</p>\n<h2 id=\"step-9-check-the-tiles\">Adım 9: döşemeleri incele</h2>\n<p>Birkaç döşemeyi tam boyutta aç ve kenarlara bak. Her döşeme temiz bir kesim göstermeli; komşu döşemeden bir şerit ya da sınırda eksik bir şerit olmamalıdır. Döşemeler bir araya geldiğinde temiz bir bölme görünmez olur.</p>\n<p>Özellikle ilk ve son döşemeyi incele. Kenar döşemeleri, görüntünün boyutlarının eşit bölünmediği ve kenar döşemelerinin boyutta bir ya da iki piksel farklı çıktığı eşit olmayan bölme sorunlarını ortaya çıkarır. Küçük bir fark normaldir ve nadiren fark edilir.</p>\n<p>İş bir ızgara ya da yapbozsa döşemeleri birlikte gör. Ekranda sırayla yerleştir ya da bir kolajda birleştir ve görüntünün iyi yeniden kurulduğunu doğrula. Bütün olarak bakıldığında yeri yanlış bir döşeme hemen fark edilir.</p>\n<p>Bir döşeme kötü görünüyorsa elle düzeltme. Bölücüye geri dön, ızgarayı ya da kaynak görüntüyü ayarla ve yeniden böl. Yeni bir bölme her döşemeyi tutarlı tutarken elle düzenlenmiş bir döşeme geri kalanından sapabilir.</p>\n<h2 id=\"step-10-reuse-the-setup\">Adım 10: ayarı yeniden kullan</h2>\n<p>İşe yarayan ayarı kaydet. Izgara boyutu, mod ve döşeme biçimi bölmeyi tanımlayan üç sayıdır ve onları yeniden kullanmak bir dizi bölmeyi tutarlı tutar. Aynı ayarla kurulmuş haftalık bir ızgara yapbozu bir dizi gibi görünür, tesadüfler seti gibi değil.</p>\n<p>Yeni bir görüntüyü aynı ayarla yükleyip aynı sayıları uygulayarak böl. Araç ziyaretler arasında hiçbir şeyi hatırlamaz; bu yüzden 8. adımda yaptığın not kayıttır. Proje dosyalarınla birlikte sakla.</p>\n<p>Kaynak görüntü biçimi değiştiğinde ayarın ayarlamaya ihtiyacı olabilir. Kare bir görüntü ve geniş bir görüntü 3'e 3 bölündüğünde farklı biçimde döşemeler verir; bu yüzden sayılar aynı olsa bile her seferinde önizlemeyi incele.</p>\n<p>Notlarına küçük bir bölme hazır ayarı kütüphanesi kur: 3'e 3 Instagram, 4'e 5 poster, 4 şeritli ekran görüntüsü ve sık kullandığın diğer bölmeler. Yazılı bir liste beş dakikalık bir işi bir dakikalık işe dönüştürür.</p>\n<h2 id=\"fixing-uneven-splits\">Eşit olmayan bölmeleri düzeltme</h2>\n<p>Eşit olmayan bölme, görüntünün boyutlarının satırlar ya da sütunlar arasında eşit bölünmediği zaman olur. 1000 piksel bir görüntü 3 sütuna bölündüğünde 333, 333 ve 334 piksel döşemeler verir, çünkü fazladan piksellerin bir yere gitmesi gerekir. Kenar döşemeleri bir piksel daha büyük çıkar.</p>\n<p>Bir piksel farkı neredeyse tüm kullanımlarda görünmezdir. Sosyal gönderiler, kaydırıcılar ve yazdırma düzenleri görünür bir dikiş olmadan bunu tolere eder. Piksel düzeyinde farkın görünür bir etkisi olmadığında kusursuz bir bölmenin peşinden koşma.</p>\n<p>Sprite sayfaları gibi piksel tam işler için kaynak görüntüyü önce kırp. Görüntüyü ızgara arasında eşit bölünen boyutlara kırp ve ardından böl. 960 piksel bir sayfa 3'e 3 bölündüğünde kalansız tam 320 piksel döşemeler verir.</p>\n<p>Doğruluk önemliyse indirmede döşeme boyutlarını incele. Döşemeleri aç ve bir oyun motorunda ya da yazdırma düzeninde kullanmadan önce boyutları doğrula; burada bir piksel farkı hizalamayı kaydırabilir.</p>\n<h2 id=\"splitting-for-a-specific-platform\">Belirli bir platform için bölme</h2>\n<p>Her platformun kendi döşeme beklentileri vardır. Instagram ızgaralarının kare döşemelere ihtiyacı vardır; bu yüzden kaynak görüntü kare olmalı ve ızgara 3'e 3 olmalıdır. Kare olmayan bir görüntü profil ızgarasını bozan kare olmayan döşemeler verir.</p>\n<p>Yazdırmanın kâğıt boyutuyla eşleşen döşemelere ihtiyacı vardır. A4 sayfalar için bölünmüş bir poster A4 oranlarında döşemelere ihtiyaç duyar; bu yüzden ızgarayı yuvarlak bir sayıdan değil, kâğıt boyutlarından belirle. Döşeme sayısı poster boyutunun sayfa boyutuna bölünmesiyle gelir.</p>\n<p>Kaydırıcıların kendi başına okunan döşemelere ihtiyacı vardır. Dikey şeritlere bölünmüş bir panorama her biri sahnenin bir bölümünü gösteren şeritler verir ve her bölüm bir kaydırmayı taşıyacak kadar ilginç olmalıdır. Yalnızca gökyüzü ya da yalnızca boş zemin olan bir şerit bir kaydırmayı boşa harcar.</p>\n<p>Platform düzeni değiştirdiğinde bölmenin de değişmesi gerekebilir. Instagram daha önce profil ızgara biçimini değiştirdi ve eski biçim için kurulmuş bir ızgara yeni biçimde kötü görünebilir. Yapboz kurmadan önce mevcut ızgarayı incele.</p>\n<h2 id=\"quick-reference\">Hızlı başvuru: bölme kontrol listesi</h2>\n<p>Büyük bir kaynak görüntü yükle, Izgara ya da şerit modu seç, satır ve sütunları belirle ya da hazır ayara dokun ve numaralı kesim çizgilerini yüzler ve metin için incele. Fotoğraflar için JPG ve şeffaflık için PNG seç.</p>\n<p>ZIP indir, döşemeleri sırayla tut ve ızgara döşemelerini ters sırada yayımla. Bir kesim kötü çıkarsa ya da döşemeler eşit olmayan çıkarsa ızgarayı ayarla ya da kaynak görüntüyü kırp ve yeniden böl.</p>\n<p>Tam kılavuz için <a href=\"/tr/blog/gorsel-bol-rehberi\">Görüntü Bölücü Kılavuzu</a> yazısını oku ve Instagram ızgarası ayrıntısı için <a href=\"/tr/blog/gorsel-bol-instagram-izgara\">Instagram Izgara ve Yapbozları için Görüntü Bölme</a> yazısını oku. Görüntünü <a href=\"/tr/gorsel-bol\">Görüntü Bölücü</a> ile böl.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Kaç satır ve sütun seçeceğimi nasıl bilirim?","answer":"Sayıyı işe uydur: Instagram ızgarası için 3'e 3, basit bir bölme için 2'ye 2 ve uzun bir ekran görüntüsü için sayfa ya da slayt sayın kadar şerit. Daha az döşeme daha büyük döşemeler demektir; bu yüzden işi yapan en küçük sayıyı kullan."},{"question":"Görüntüm eşit bölünmezse ne olur?","answer":"Kenar döşemeleri geri kalandan bir ya da iki piksel daha büyük çıkar, çünkü fazladan piksellerin bir yere gitmesi gerekir. Bir piksel farkı normal kullanımda görünmezdir. Piksel tam işler için kaynak görüntüyü önce eşit bölünen boyutlara kırp."},{"question":"Ekran görüntüsünü yazdırılabilir sayfalara bölebilir miyim?","answer":"Evet. Yatay Şeritler kullan ve şerit sayısını istediğin sayfa sayısına göre belirle. Her şerit kendi sayfasına yazdırılır ve şeritler birlikte ekran görüntüsünün tamamını içerir. Her şeridin kâğıt boyutuyla eşleşmesi için sayıyı seç."},{"question":"Döşemeleri nasıl yeniden birleştiririm?","answer":"Onları numaralı düzende, soldan sağa ve yukarıdan aşağıya yerleştir; döşeme bir sol üst köşeden başlar. Bir Instagram ızgarası için onları ters sırada, son döşemeden ilke doğru yayımla; böylece doğru konumlarda kalırlar."},{"question":"Döşemeler için hangi biçimi seçmeliyim?","answer":"Fotoğraflar ve küçük dosyaların önemli olduğu her kullanım için, sosyal gönderiler gibi, JPG seç. Grafikler, metin ve şeffaf görüntüler için PNG seç; çünkü PNG her pikseli tam tutar ve şeffaflığı korur."},{"question":"Görüntüyü telefonumda bölebilir miyim?","answer":"Evet, bölücü masaüstünün yanı sıra telefon ve tablet tarayıcılarında da çalışır. Fotoğraf galerinden yükle, ızgarayı belirle ve ZIP indir. Büyük bir kaynak görüntü daha iyi çalışır; bu yüzden sıkıştırılmış bir kopya yerine orijinal fotoğrafı kullan."}];
